def note(message):
    with open('events.txt','a',newline='') as target:
        target.write(message+'\n')
def read():
    note('default')
    with open('number.txt') as source:
        return int(source.read())
class Number:
    def __iadd__(self,other):
        note('iadd')
        with open('number.txt') as source:
            return int(source.read())+other
def f(value):
    value+=1
    return value
print(f(Number()))
